#!/bin/bash
set -euo pipefail

RESULTS_DIR=${1:-${FAST_GL_RESULTS_DIR:-}}
if [[ -z "${RESULTS_DIR}" ]]; then
    echo "Usage: $0 RESULTS_DIR [SLURM_ACCOUNT]" >&2
    exit 2
fi
MANIFEST="${RESULTS_DIR}/current_run.env"
if [[ ! -f "${MANIFEST}" ]]; then
    echo "Missing run manifest: ${MANIFEST}" >&2
    exit 2
fi

# Generated by submit_selected_sequences.sh with shell-quoted values.
# shellcheck disable=SC1090
source "${MANIFEST}"
ACCOUNT=${2:-${FAST_GL_RUN_ACCOUNT:-}}
if [[ -z "${ACCOUNT}" ]]; then
    echo "SLURM account is missing from the manifest; pass it as argument 2." >&2
    exit 2
fi

export FAST_GL_RESULTS_DIR=${RESULTS_DIR}
PARTITION=${FAST_GL_RUN_PARTITION:-standard}
mkdir -p "${FAST_GL_RESULTS_DIR}/logs" "${FAST_GL_RESULTS_DIR}/combined"

JOB_ID=$(sbatch --parsable \
    --account="${ACCOUNT}" --partition="${PARTITION}" \
    --time="${FAST_GL_PROCESS_TIME:-02:00:00}" \
    --mem="${FAST_GL_PROCESS_MEMORY:-8G}" \
    --output="${FAST_GL_RESULTS_DIR}/logs/process-%j.out" \
    --export=ALL "${FAST_GL_WORKFLOW_DIR}/process_results.sbatch")

printf 'Processing job: %s\n' "${JOB_ID}"
printf 'Output log:     %s/logs/process-%s.out\n' "${FAST_GL_RESULTS_DIR}" "${JOB_ID}"
printf 'Combined data:  %s/combined\n' "${FAST_GL_RESULTS_DIR}"
